{
  "host": "source-postgres-db-backend",
  "port": 5432,
  "database": "test_db",
  "schemas": ["public"],
  "username": "postgres",
  "password": "test_password",
  "ssl_mode": {
    "mode": "prefer"
  },
  "tunnel_method": {
    "tunnel_method": "NO_TUNNEL"
  },
  "replication_method": {
    "method": "CDC",
    "replication_slot": "airbyte_slot",
    "publication": "airbyte_publication",
    "initial_waiting_seconds": 120
  }
}

-- Initialize the PostgreSQL logical replication CDC fixture.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_replication_slots
    WHERE slot_name = 'airbyte_slot'
  ) THEN
    PERFORM pg_drop_replication_slot('airbyte_slot');
  END IF;
END
$$;

DROP PUBLICATION IF EXISTS airbyte_publication;
DROP TABLE IF EXISTS public.users;

CREATE TABLE public.users (
  id SERIAL PRIMARY KEY,
  name VARCHAR(64) NOT NULL,
  email VARCHAR(200) NOT NULL
);

INSERT INTO public.users (name, email) VALUES
  ('alice', 'alice@example.com'),
  ('bob', 'bob@example.com'),
  ('carol', 'carol@example.com');

CREATE PUBLICATION airbyte_publication FOR TABLE public.users;
SELECT pg_create_logical_replication_slot('airbyte_slot', 'pgoutput');

{
  "streams": [
    {
      "stream": {
        "name": "users",
        "json_schema": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string"
            },
            "id": {
              "airbyte_type": "integer",
              "type": "number"
            },
            "email": {
              "type": "string"
            },
            "_ab_cdc_lsn": {
              "type": "number"
            },
            "_ab_cdc_updated_at": {
              "type": "string"
            },
            "_ab_cdc_deleted_at": {
              "type": "string"
            }
          }
        },
        "supported_sync_modes": ["full_refresh", "incremental"],
        "source_defined_cursor": true,
        "default_cursor_field": ["_ab_cdc_lsn"],
        "source_defined_primary_key": [["id"]],
        "namespace": "public",
        "is_resumable": true,
        "is_file_based": false
      },
      "sync_mode": "incremental",
      "destination_sync_mode": "append_dedup",
      "primary_key": [["id"]],
      "cursor_field": ["_ab_cdc_lsn"],
      "generation_id": 0,
      "minimum_generation_id": 0,
      "sync_id": 0,
      "destination_object_name": "users",
      "include_files": false
    }
  ]
}

